module multi_booth_8bit (
    output reg [15:0] p,
    output reg rdy,
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b
);
    reg [4:0] ctr;

    reg [15:0] multiplier, multiplicand;
    always @(posedge clk or posedge (reset)) begin
        if(reset==1'b1) begin
            multiplier <= {{8{a[7]}}, a};
            multiplicand <= {{8{b[7]}}, b};
            rdy <= 1'b0;
            p <= 16'h0000;
            ctr <= 5'd0;
        end else begin
            if(ctr<5'd16) begin
                multiplicand <= multiplicand << 1;

                if(multiplier[ctr]==1'b1) begin
                    p <= p + multiplicand;
                end

                ctr <= ctr + 1;
            end else begin
                rdy <= 1'b1;
            end
        end
    end

endmodule
